myv_wyvern.0201:
myv_wyvern.0201 = {
	type = character_event
	window = myv_wyvern_duel_event
	override_background = { reference = myv_wyvern_duel }
	title = myv_wyvern.0201.t
	desc = {
		first_valid = {
			triggered_desc = { trigger = { var:myv_slay_outdoor_battle = 1 } desc = myv_wyvern.0201.desc_outdoor }
			desc = myv_wyvern.0201.desc
		}
	}
	theme = martial
	left_portrait = {
		character = root
		animation = aggressive_sword
		outfit_tags = { military_outfit }
	}
	right_portrait = {
		character = scope:myv_slay_wyvern_target
		animation = myv_wyvern_main
	}

	option = {
		name = myv_wyvern.0201.a
		custom_tooltip = myv_wyvern.0201.loot_chances_tt
		add_prestige = 500
		hidden_effect = {
			myv_slay_create_trophy_effect = yes
		}
		myv_slay_reset_state_effect = yes
		scope:myv_slay_wyvern_target = {
			if = {
				limit = { myv_is_living_wyvern = yes }
				death = {
					death_reason = death_myv_wyvern_slain
					killer = root
				}
				root = { myv_grant_wyvern_slayer_reward_effect = yes }
			}
		}
	}
}

